"""Build an offline artwork review page from packaged pilot assets."""
from pathlib import Path
import html
import json

base = Path(__file__).resolve().parent
manifest = json.loads((base/'pilot/manifest.json').read_text())
cards = []
for clip in manifest['clips']:
    key = clip['id']
    title = html.escape(key.replace('-', ' ').capitalize())
    prompt = clip.get('prompt', 'prompts/'+('read-loop-v2' if key=='read-loop' else key)+'.txt')
    extra = ' · <a href="prompts/read-entry-v2.txt">Endpoint correction</a>' if key=='read-entry' else ''
    cards.append(f'''<article data-id="{key}">
<h2>{title}</h2><p class="meta">{clip['from']} → {clip['to']} · {clip['durationMs']/1000:g}s · {'loop' if clip['loop'] else 'one-shot; preview repeats'}</p>
<div class="stage checker"><img class="main" width="256" height="256" src="pilot/{clip['preview']}" alt="{title} animated preview"></div>
<div class="controls"><button class="play" type="button">Play animation</button><label><input class="mirror" type="checkbox"> Mirror</label></div>
<label class="scrub">Inspect frame <output>1</output>/12<input type="range" min="0" max="11" value="0" aria-label="Inspect {title} frames"></label>
<div class="small"><div class="stage light"><img width="96" height="96" src="pilot/{clip['preview']}" alt="{title} at 96 pixels"><span>96 px · light</span></div><div class="stage dark"><img width="128" height="128" src="pilot/{clip['preview']}" alt="{title} at 128 pixels"><span>128 px · dark</span></div></div>
<p class="links"><a href="pilot/{clip['file']}">Sprite strip</a> · <a href="{prompt}">Exact prompt</a>{extra}</p>
</article>''')
sequences=[]
for seq in manifest['sequences']:
    chain=html.escape(' → '.join(seq['clips']))
    sequences.append(f'''<article><h2>{html.escape(seq['id'].replace('-',' ').capitalize())}</h2><div class="stage checker"><img width="256" height="256" src="pilot/{seq['preview']}" alt="{seq['id']} connected animation sequence"></div><p class="meta">{seq['durationMs']/1000:g}s · preview repeats</p><p class="chain">{chain}</p><a href="pilot/{seq['preview']}">Open connected preview</a></article>''')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kōくん — animation pilot review</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#eee7d8;color:#243344;font:15px/1.5 system-ui,sans-serif}main{max-width:1260px;margin:auto;padding:32px 24px}h1{font:600 36px/1.2 Georgia,serif;margin:10px 0}h2{font:600 22px/1.25 Georgia,serif;margin:0 0 8px}h3{font:600 28px Georgia,serif}.eyebrow{font:12px monospace;letter-spacing:2px;color:#a14029}.notice{background:#fff7e3;border:1px solid #b29a70;padding:14px 18px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:20px 0}article{background:#fffaf0;border:1px solid #c4b79d;border-radius:8px;padding:16px;min-width:0}.meta{font-size:12px;color:#5a635f}.stage{display:flex;justify-content:center;align-items:center;flex-direction:column;overflow:hidden;min-height:150px}.stage img{display:block;object-fit:contain;image-rendering:pixelated}.checker{background-color:#f2f2ef;background-image:linear-gradient(45deg,#d4d4d0 25%,transparent 25%),linear-gradient(-45deg,#d4d4d0 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#d4d4d0 75%),linear-gradient(-45deg,transparent 75%,#d4d4d0 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.light{background:#fff}.dark{background:#1e2835;color:#eee}.color{background:#b4ccc1}.small{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}.small span{font:11px monospace}.controls{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:12px 0}button{font:inherit;font-size:13px;border:1px solid #728178;border-radius:4px;background:#fffaf0;color:#243344;padding:6px 9px;cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #ae4930;outline-offset:3px}.scrub{font-size:12px;display:block}.scrub input{display:block;width:100%;accent-color:#a14029}.controls label{font-size:12px}a{color:#963b27}.links{font-size:12px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.toolbar button[aria-pressed=true]{background:#243344;color:#fff}.chain{font:12px/1.6 monospace;overflow-wrap:anywhere}.wide{width:100%;height:auto}.ref{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.ref img{width:100%;height:230px;object-fit:contain;image-rendering:pixelated}footer{border-top:1px solid #c4b79d;padding-top:20px;margin-top:30px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){main{padding:20px 12px}.grid,.ref{grid-template-columns:1fr}.controls{flex-wrap:wrap}h1{font-size:30px}}
</style><main><div class="eyebrow">KŌ · V1.3 · PILOT REVIEW</div><h1>A knowledgeable little companion.</h1>
<p>Approved character: <strong>A, no collar</strong>. Four pilot routines, their connecting motions, and two shared posture transitions. Artwork only; no browser-pet feature code.</p>
<p class="notice"><strong>Review gate 2 of 2:</strong> pilot approval is pending. Inspect tail count, expression, movement, prop continuity, scale, and connected sequences. One-shot previews repeat for review convenience. Transparent WebP previews and sprite strips retain alpha; display backgrounds are not baked in.</p>
<div class="toolbar" aria-label="Large preview background"><button data-bg="checker" aria-pressed="true">Checkerboard</button><button data-bg="light" aria-pressed="false">Light</button><button data-bg="dark" aria-pressed="false">Dark</button><button data-bg="color" aria-pressed="false">Green</button></div>
<div class="grid">'''+''.join(cards)+'''</div><h3>Connected sequences</h3><p>These play generated clips in order, without page movement or random behavior logic. Check each join for visible changes in pose, proportions, or placement.</p><div class="grid">'''+''.join(sequences)+'''</div><h3>Character references</h3><div class="ref"><div class="stage checker"><img src="references/front.png" alt="Front reference"></div><div class="stage checker"><img src="references/standing-profile-v2.png" alt="Standing right profile reference"></div><div class="stage checker"><img src="references/seated-three-quarter.png" alt="Seated right three-quarter reference"></div></div>
<h3>Pilot contact sheet</h3><a href="pilot/contact-sheet.png"><img class="wide" src="pilot/contact-sheet.png" alt="All generated pilot clips"></a><footer><p><a href="pilot/manifest.json">Manifest</a> · <a href="pilot/verification.json">Automated checks</a> · <a href="README.md">Production plan and review notes</a> · <a href="catalogue.json">Full 24-routine catalogue</a></p><p>Generated with the built-in image generation tool. Original source sheets and exact prompts are retained locally. Remaining routines follow pilot approval.</p></footer></main>
<script>
document.querySelectorAll('[data-id]').forEach(card=>{const img=card.querySelector('img.main'),id=card.dataset.id,animated=img.getAttribute('src'),range=card.querySelector('input[type=range]'),output=card.querySelector('output');range.addEventListener('input',()=>{output.value=Number(range.value)+1;img.src='pilot/frames/'+id+'/'+String(range.value).padStart(2,'0')+'.png'});card.querySelector('.play').addEventListener('click',()=>{img.src=animated+'?replay='+Date.now()});card.querySelector('.mirror').addEventListener('change',e=>{card.querySelectorAll('img').forEach(i=>i.style.transform=e.target.checked?'scaleX(-1)':'')})});
document.querySelectorAll('[data-bg]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-bg]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('.stage').forEach(stage=>{if(stage.closest('.small'))return;stage.classList.remove('checker','light','dark','color');stage.classList.add(button.dataset.bg)})}));
</script></html>'''
page=page.replace('references/seated-three-quarter.png','references/seated-three-quarter-complete.png')
page=page.replace('<h3>Character references</h3>', '<h3>At the intended pet size</h3><img class="wide" src="pilot/readability.png" alt="Four routines at 128 pixels on light and 96 pixels on dark"><h3>Clip joins</h3><p>Each pair shows the final frame of one clip beside the first frame of the next, at 128 pixels. Compare placement, proportions, and pose.</p><img class="wide" src="pilot/joins.png" alt="Twelve pairs of adjoining clip endpoints"><h3>Character references</h3><p><a href="references/character-reference.png">Complete six-view reference sheet</a></p>')
(base/'pilot-review.html').write_text(page)
print(f'Wrote pilot-review.html with {len(cards)} clips and {len(sequences)} connected sequences.')
